fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    let n = s1.len();
    // Since s1, s2, and s3 have equal length, length checks are not mandatory but can be done for sanity.
    assert_eq!(s2.len(), n);
    assert_eq!(s3.len(), n);

    // Preallocate the result vector with capacity 3 * n
    let mut res = Vec::with_capacity(3 * n);

    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }

    res
}